// Checks the hand-written types against docs.tsv both ways: every documented field must match,
// and every field in the types must be documented. Asserted in assertions.ts, generated by docs.ts.

import type {
	AlimtalkMessageRegular,
	AlimtalkMessageTemplate,
	BrandMessageBasic,
	BrandMessageFree,
	BrandMessageTemplate,
} from '#bizgo/v1/channels/index.ts';
import type * as List from '#bizgo/v1/reservation/list/GET/types.ts';
import type * as Create from '#bizgo/v1/reservation/POST/types.ts';
import type * as Cancel from '#bizgo/v1/reservation/resvKey/cancel/POST/types.ts';
import type * as ListDestinations from '#bizgo/v1/reservation/resvKey/destinations/GET/types.ts';
import type * as DeleteDestination from '#bizgo/v1/reservation/resvKey/destinations/msgKey/DELETE/types.ts';
import type * as AddDestinations from '#bizgo/v1/reservation/resvKey/destinations/POST/types.ts';
import type * as Get from '#bizgo/v1/reservation/resvKey/GET/types.ts';
import type * as Update from '#bizgo/v1/reservation/resvKey/PUT/types.ts';
import type * as Resume from '#bizgo/v1/reservation/resvKey/resume/POST/types.ts';
import type * as Stop from '#bizgo/v1/reservation/resvKey/stop/POST/types.ts';
import type * as Send from '#bizgo/v1/send/omni/POST/types.ts';
import type { Destination } from '#bizgo/v1/types.ts';

// Path parameters are function arguments (e.g. `getReservation(resvKey, opts)`), so they aren't checked.
export type Endpoints = {
	'POST /api/comm/v1/send/omni': {
		'Body Parameters': Send.RequestBody;
		'Returns': Send.ResponseBody;
	};
	'POST /api/comm/v1/reservation': {
		'Body Parameters': Create.RequestBody;
		'Returns': Create.ResponseBody;
	};
	'GET /api/comm/v1/reservation/list': {
		'Query Parameters': List.Query;
		'Returns': List.ResponseBody;
	};
	'GET /api/comm/v1/reservation/resvKey/{resvKey}': { Returns: Get.ResponseBody };
	'PUT /api/comm/v1/reservation/resvKey/{resvKey}': {
		'Body Parameters': Update.RequestBody;
		'Returns': Update.ResponseBody;
	};
	'POST /api/comm/v1/reservation/resvKey/{resvKey}/cancel': { Returns: Cancel.ResponseBody };
	'POST /api/comm/v1/reservation/resvKey/{resvKey}/stop': { Returns: Stop.ResponseBody };
	'POST /api/comm/v1/reservation/resvKey/{resvKey}/resume': { Returns: Resume.ResponseBody };
	'POST /api/comm/v1/reservation/resvKey/{resvKey}/destinations': {
		'Body Parameters': AddDestinations.RequestBody;
		'Returns': AddDestinations.ResponseBody;
	};
	'GET /api/comm/v1/reservation/resvKey/{resvKey}/destinations': {
		'Query Parameters': ListDestinations.Query;
		'Returns': ListDestinations.ResponseBody;
	};
	'DELETE /api/comm/v1/reservation/resvKey/{resvKey}/destinations/msgKey/{msgKey}': {
		Returns: DeleteDestination.ResponseBody;
	};
};

type Flow<Body, Item> = Omit<Body, 'messageFlow'> & { messageFlow: Item[] };

// Sections that document only one member of a union. Others are checked against the endpoint's body,
// where `messageFlow[].<channel>` already narrows to the channel's message type.
type Sections = {
	'comm/kakao-alimtalk': {
		'알림톡 발송': Flow<Send.RequestBody, { alimtalk: AlimtalkMessageRegular }>;
		'템플릿 자동 치환 발송': Flow<Send.TemplateRequestBody, { alimtalk: AlimtalkMessageTemplate }>;
		'예약 발송': Flow<Create.RequestBody, { alimtalk: AlimtalkMessageRegular }>;
	};
	'comm/kakao-brand': {
		'기본형 메시지 발송': Flow<Send.RequestBody, { brandmessage: BrandMessageBasic }>;
		'기본형 템플릿 자동 치환 발송': Flow<
			Send.TemplateRequestBody,
			{ brandmessage: BrandMessageTemplate }
		>;
		'자유형 메시지 발송': Flow<Send.RequestBody, { brandmessage: BrandMessageFree }>;
		'기본형 예약 발송': Flow<Create.RequestBody, { brandmessage: BrandMessageBasic }>;
		'자유형 예약 발송': Flow<Create.RequestBody, { brandmessage: BrandMessageFree }>;
	};
};

type Root<Page, Endpoint, Section, Group> = Group extends 'Path Parameters'
	? Opaque
	: Group extends 'Body Parameters'
		? Page extends keyof Sections
			? Section extends keyof Sections[Page]
				? Sections[Page][Section]
				: Body<Endpoint, Group>
			: Body<Endpoint, Group>
		: Body<Endpoint, Group>;

type Body<Endpoint, Group> = Endpoint extends keyof Endpoints
	? Group extends keyof Endpoints[Endpoint]
		? Endpoints[Endpoint][Group]
		: never
	: never;

// Fields under an index signature (e.g. Record<string, unknown>) aren't checked.
declare const opaque: unique symbol;
type Opaque = { [opaque]: true };

type Element<T> = T extends readonly (infer E)[] ? E : never;

// Resolves one path segment (e.g. `messageFlow[]`), distributing over unions.
type Step<T, Segment extends string> = T extends Opaque
	? Opaque
	: string extends keyof T
		? Opaque
		: Segment extends `${infer Key}[]`
			? Key extends keyof T
				? Element<NonNullable<T[Key]>>
				: never
			: Segment extends keyof T
				? NonNullable<T[Segment]>
				: never;

type Parent<T, Path extends string> = Path extends `${infer Head}.${infer Rest}`
	? Parent<Step<T, Head>, Rest>
	: T;
type Last<Path extends string> = Path extends `${string}.${infer Rest}` ? Last<Rest> : Path;

type Base<Type> = Type extends `${infer Item} Array`
	? Base<Item>[]
	: Type extends 'String'
		? string
		: Type extends 'Integer' | 'Long' | 'Number' | 'Double'
			? number
			: Type extends 'Boolean'
				? boolean
				: Type extends 'Object'
					? object
					: unknown;

// Distributes over the parent union, keeping only the members that have the key.
// A key typed `never` (e.g. `fileKey?: never`) marks a member without the field.
type Members<T, Key extends string> = T extends unknown
	? T extends Opaque
		? T
		: string extends keyof T
			? Opaque
			: Key extends keyof T
				? [NonNullable<T[Key]>] extends [never]
					? never
					: T
				: never
	: never;

// Distributes over the members, so a field's type, and its required flag, must match in every member that has it.
type Match<T, Key extends string, Type, Required> = T extends Opaque
	? true
	: Key extends keyof T
		? [NonNullable<T[Key]>] extends [Base<Type>]
			? Required extends 'Yes'
				? {} extends Pick<T, Key>
					? 'should be required'
					: true
				: true
			: `should be ${Type & string}`
		: never;

// A field is optional when any member of the parent union lacks it or makes it optional
// (e.g. `messageFlow[].sms`, since other channels lack it).
type Optional<T, Key extends string> = T extends unknown
	? T extends Opaque
		? true
		: Key extends keyof T
			? [NonNullable<T[Key]>] extends [never]
				? true
				: {} extends Pick<T, Key>
					? true
					: false
			: true
	: never;

type Field<Parent, Key extends string, Type, Required> = [Members<Parent, Key>] extends [never]
	? 'missing'
	:
			| Match<Members<Parent, Key>, Key, Type, Required>
			| (Required extends 'No'
					? true extends Optional<Parent, Key>
						? true
						: 'should be optional'
					: true);

export type Check<
	Page extends string,
	Endpoint extends string,
	Section extends string,
	Group extends string,
	Path extends string,
	Type extends string,
	Required extends string,
> = Field<
	Parent<Root<Page, Endpoint, Section, Group>, Path>,
	Last<Path>,
	Type,
	Group extends 'Returns' ? '' : Required // Returns are all documented as optional
>;

export type AssertTrue<T extends true> = T;

// Every field path in a type, in the docs' notation (e.g. `messageFlow[].sms.from`).
// Fields under an index signature (e.g. Record<string, unknown>) aren't listed.
type Paths<T, Prefix extends string = ''> = T extends unknown
	? {
			[Key in keyof T & string]-?: [NonNullable<T[Key]>] extends [never]
				? never
				: `${Prefix}${Key}` | Nested<NonNullable<T[Key]>, `${Prefix}${Key}`>;
		}[keyof T & string]
	: never;

type Nested<V, Path extends string> = V extends readonly (infer E)[]
	? E extends object
		? Paths<E, `${Path}[].`>
		: never
	: V extends object
		? string extends keyof V
			? never
			: Paths<V, `${Path}.`>
		: never;

// Fields the docs don't list, but the sandbox returns (see the integration tests).
// https://github.com/hyunbinseo/new-request/issues/17
type Undocumented =
	| 'POST /api/comm/v1/reservation | Returns | data.data.destinations[].ref'
	| `GET /api/comm/v1/reservation/resvKey/{resvKey}/destinations | Returns | data.data.destinations[].destData.${keyof Destination}`;

// Paths in the types that the docs don't list for the endpoint, as `<endpoint> | <group> | <path>`.
export type Extra<
	Endpoint extends keyof Endpoints,
	Group extends string,
	Documented extends string,
> = Exclude<`${Endpoint} | ${Group} | ${Paths<Body<Endpoint, Group>>}`, Documented | Undocumented>;

export type AssertNever<T extends never> = T;
